/* Offline UI shared by the Android application and the browser preview. */
'use strict';
const L = window.Ledger;
const H = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
 list:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 8h6M9 12h6M9 16h4"/>',
 chart:'<path d="M4 3v17h17M8 15v-4M13 15V6M18 15V9"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrow:'<path d="m9 5 7 7-7 7"/>',
 left:'<path d="m15 5-7 7 7 7"/>',
 close:'<path d="m6 6 12 12M18 6 6 18"/>',
 bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7V2Z"/>',
 station:'<rect x="4" y="3" width="11" height="17" rx="2"/><path d="M7 7h5M2 21h15M15 9h3v7a2 2 0 0 0 4 0V7l-3-3M8 11l-1 3h3l-1 3"/>',
 car:'<path d="m4 10 2-6h12l2 6M3 10h18v8H3ZM6 18v2M18 18v2M6 14h2M16 14h2"/>',
 bag:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V4h8v3M3 12c6 3 12 3 18 0M12 12v4"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',
 pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
 locate:'<circle cx="12" cy="12" r="6"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/><circle cx="12" cy="12" r="1"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
 shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z"/><path d="m8 12 3 3 5-6"/>',
 edit:'<path d="m16 3 5 5-12 12-6 1 1-6ZM14 5l5 5"/>',
 trash:'<path d="M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',
 link:'<path d="M14 3h7v7M21 3l-9 9M10 3H3v18h18v-7"/>',
 copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',
 share:'<circle cx="18" cy="4" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="20" r="3"/><path d="m8 10 7-4m-7 8 7 4"/>'
};
function icon(name) {return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.bolt}</svg>`;}
function btn(label,action,cls='secondary',ico='') {return `<button class="${cls}" data-action="${action}" type="button">${ico?icon(ico):''}${H(label)}</button>`;}
const native = window.Android && typeof window.Android.load === 'function' ? window.Android : null;
const demo = !native && new URLSearchParams(location.search).get('demo')==='1';
const storageKey = demo?'charge-ledger-demo-v1':'charge-ledger-v1';
let dataRevision=0,recordLimit=80,searchTimer=null;
let storageError='',state,screen='home',category='all',grain='month',anchor=L.todayTime().slice(0,10),listSearch='',listStart='',listEnd='',modal='',editId=null,formLocation=null,locateToken=0,toastTimer=null,exportContent='',exportRecords=[],pendingRestore=null;
function demoData() {
  const s=L.emptyState(),now=L.todayTime().slice(0,10),month=now.slice(0,7);s.settings.vehicle='我的新能源汽车 · 演示';
  const rows=[['02',28.65,25.79,'daily','星星充电 · 城西银泰站','杭州 · 西湖区','错峰补电',0],['05',42.8,39.38,'daily','特来电 · 科技园站','杭州 · 余杭区','',5],['08',36.52,48.57,'business','国家电网 · 嘉兴服务区','浙江 · 嘉兴','沪杭出差途中',''],['11',51.26,46.13,'daily','星星充电 · 城西银泰站','杭州 · 西湖区','谷时充电',0],['13',31.8,43.88,'business','小桔充电 · 虹桥站','上海 · 闵行区','客户拜访',8]];
  rows.filter(r=>Number(r[0])<=Number(now.slice(8))).forEach((r,i)=>s.records.push({id:'demo_'+i,time:`${month}-${r[0]}T${i%2?'21:30':'13:15'}`,timezone:'Asia/Shanghai',energyMilli:Math.round(r[1]*1000),amountCents:Math.round(r[2]*100),parkingCents:r[7]===''?null:r[7]*100,category:r[3],station:r[4],address:r[5],note:r[6],operator:r[4].split(' · ')[0],trip:r[3]==='business'?'华东出差':'',socStart:20,socEnd:80,duration:42,odometer:null,location:null}));
  const old=L.shift(month+'-01',-5);s.records.push({id:'demo_old',time:old+'T22:15',timezone:'Asia/Shanghai',energyMilli:35500,amountCents:3195,category:'daily',station:'星星充电 · 城西银泰站',address:'杭州 · 西湖区',note:'',trip:'',operator:'星星充电',parkingCents:null,location:null});return s;
}
try {const raw=native?native.load():localStorage.getItem(storageKey);state=raw?L.validateState(JSON.parse(raw)):(demo?demoData():L.emptyState());}
catch(e){storageError='已有数据读取失败。为保护原始数据，已暂停写入，请通过备份恢复。';state=L.emptyState();console.error(e);}
function persist(next,restoring=false) { if(storageError&&!restoring){toast(storageError);return false;}try{next.updatedAt=L.todayTime();L.validateState(next);const raw=JSON.stringify(next);if(native){if(!native.save(raw))throw new Error('无法写入设备存储');}else localStorage.setItem(storageKey,raw);state=next;dataRevision++;if(restoring)storageError='';return true;}catch(e){toast('保存失败：'+e.message);return false;} }
function mutate(fn){const s=JSON.parse(JSON.stringify(state));fn(s);return persist(s);}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600);}
function heading(title,subtitle='',action='new',ico='plus'){return `<header class="page-header"><div><h1>${H(title)}</h1>${subtitle?`<p class="muted small">${H(subtitle)}</p>`:''}</div>${action?`<button class="icon-button" data-action="${action}" aria-label="${action==='new'?'记录充电':'导出记录'}">${icon(ico)}</button>`:''}</header>`;}
function tabs(options,value,action){return `<div class="tabs" role="group">${options.map(([v,t])=>`<button class="tab ${v===value?'selected':''}" data-action="${action}" data-value="${H(v)}" aria-pressed="${v===value}">${H(t)}</button>`).join('')}</div>`;}
function categoryTabs(){return tabs([['all','全部用电'],['daily','日常用电'],['business','差旅用电']],category,'category');}
function empty(message='还没有充电记录',sub='记录第一次充电，开始了解你的用电习惯。',action='new',label='记录充电'){return `<div class="empty"><div class="empty-icon">${icon('station')}</div><h3>${H(message)}</h3><p>${H(sub)}</p>${action?btn(label,action,'secondary','plus'):''}</div>`;}
function recordTitle(r){return r.station||r.trip||(r.recordKind==='trip_expense_summary'?'差旅行程合计':'充电费用');}
function recordsHTML(records){return `<div class="record-list">${records.length?records.map(r=>`<button class="record" data-action="detail" data-id="${H(r.id)}"><span class="station-icon ${r.category}">${icon(r.recordKind==='trip_expense_summary'?'bag':'station')}</span><span class="record-content"><span class="record-title">${H(recordTitle(r))}</span><span class="record-meta"><span>${H(L.displayDate(r).slice(5))}</span><span class="badge ${r.category}">${L.categories[r.category].slice(0,2)}</span><span>${r.recordKind==='trip_expense_summary'?'行程合计':(r.energyMilli==null?'电量未记录':L.priceText(r)+' 元/度')}</span></span></span><span class="record-amount">¥${L.money(r.amountCents)}<span class="record-energy">${r.energyMilli==null?'电量待补':L.energy(r.energyMilli)+' kWh'}</span></span></button>`).join(''):empty('没有匹配的记录','调整筛选条件，或记录一次新的充电。')}</div>`;}
function home(){
 const p=L.period(L.todayTime(),'month'),rs=L.filter(state.records,{start:p.start,until:p.end,grain:'month'}),s=L.sum(rs),d=L.sum(rs.filter(r=>r.category==='daily')),b=L.sum(rs.filter(r=>r.category==='business')),budget=state.settings.budgetCents,ratio=budget?Math.min(s.amountCents/budget,1):0;
 return `<header class="page-header"><div class="brand"><img src="icon.svg" alt="" class="brand-icon">充电手账</div><span class="status-pill"><span class="status-dot"></span>本地记录</span></header><div class="greeting"><div class="eyebrow">${H(state.settings.vehicle)}</div><h1>每次补能，<span>心中有数。</span></h1><p class="muted medium">日常与远行，都记在这里。</p></div><section class="card hero" aria-label="本月充电概览"><div class="hero-top"><span class="medium">${p.label} · 充电支出</span>${btn('查看统计','stats','text-button')}</div><div class="hero-amount number"><span class="currency">¥</span>${L.money(s.amountCents)}</div><div class="hero-caption">${s.count?'已记 '+s.count+' 条费用 · '+s.tripSummaryCount+' 条行程合计':'第一笔费用，就是故事的开始'}</div><div class="charge-conduit" aria-hidden="true"><span class="conduit-icon">${icon('bolt')}</span><svg class="energy-rail" viewBox="0 0 330 42" fill="none"><path d="M0 22H33l8-11 9 23 10-30 10 19h33l8-9 8 18 9-26 10 17h38l8-9 9 20 9-30 10 19h40l8-10 9 22 10-29 9 17h24" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><circle cx="307" cy="21" r="4" fill="currentColor"/></svg></div><div class="hero-bottom"><div><div class="stat-label">已知电量</div><div class="stat-value number">${L.energySummary(s)}<span class="stat-unit">度</span></div></div><div><div class="stat-label">有电量均价</div><div class="stat-value number">${L.priceText(s)}<span class="stat-unit">元/度</span></div></div><div><div class="stat-label">费用记录</div><div class="stat-value number">${s.count}<span class="stat-unit">条</span></div></div></div></section>${btn('记录充电费用','new','primary full','plus')}<div class="section-heading"><h2>日常与远行</h2><span class="small muted">本月分类开销</span></div><div class="split-grid">${[['daily','car',d],['business','bag',b]].map(([c,i,t])=>`<button class="mini-card" data-action="category-stats" data-value="${c}"><span class="topline ${c==='business'?'teal':'blue'}">${icon(i)}${L.categories[c]}</span><div class="stat-value number">¥${L.money(t.amountCents)}</div><p class="small muted">${t.count} 条费用 · ${t.tripSummaryCount} 条合计</p></button>`).join('')}</div><div class="section-heading"><h2>最近记录</h2>${btn('全部明细','records','text-button')}</div>${state.records.length?recordsHTML(L.filter(state.records).slice(0,3)):`<div class="record-list">${empty('还没有费用记录','只知道金额也可以记录，电量和地点可稍后补齐。','new','记录第一笔')}</div>`}<div class="section-heading"><h2>月度预算</h2>${btn('设置','settings','text-button')}</div><section class="card budget-row"><svg class="budget-ring" viewBox="0 0 64 64" aria-label="预算已使用${Math.round(ratio*100)}%"><circle cx="32" cy="32" r="26" fill="none" stroke="#dce5f0" stroke-width="5"/><circle class="budget-progress" cx="32" cy="32" r="26" fill="none" stroke="#386ce9" stroke-width="5" stroke-linecap="round" stroke-dasharray="${ratio*163.36} 163.36" transform="rotate(-90 32 32)"/><text x="32" y="37" text-anchor="middle" fill="#386ce9" font-size="14" font-family="sans-serif" font-weight="700">${budget?Math.round(s.amountCents/budget*100)+'%':'—'}</text></svg><div class="budget-text"><h3>${budget?(s.amountCents>budget?'本月充电费用超出预算':'本月预算 ¥'+L.money(budget)):'尚未设置预算'}</h3><p>${budget?(s.amountCents>budget?'已超出 ¥'+L.money(s.amountCents-budget):'剩余 ¥'+L.money(budget-s.amountCents)):'在“我的”中设置预算'} · 停车费另计</p></div></section><p class="small muted coverage-note">${H(L.coverage(s))}</p>`;
}
function recordsPage(){const rs=L.filter(state.records,{category,search:listSearch,start:listStart,end:listEnd}),s=L.sum(rs);return `${heading('充电明细','每次补能，都有迹可循。','export','download')}<div class="search-box">${icon('search')}<input id="record-search" class="input" type="search" placeholder="搜索地点、备注或行程" value="${H(listSearch)}" aria-label="搜索记录"></div>${categoryTabs()}<div class="date-range"><label>开始日期<input id="list-start" type="date" class="input" value="${listStart}"></label><label>结束日期<input id="list-end" type="date" class="input" value="${listEnd}"></label></div><div class="total-strip"><div><span>充电费用 · 元</span><b>${L.money(s.amountCents)}</b></div><div><span>已知电量 · 度</span><b>${L.energySummary(s)}</b></div></div><p class="small muted range-note">仅记月份的合计需完整落在筛选范围内才会纳入。</p><div class="caption-line"><p class="record-count">${rs.length} 条记录${category==='all'?'':' · '+L.categories[category]}</p>${listStart||listEnd||listSearch?btn('重置筛选','reset-filter','text-button'):''}</div>${recordsHTML(rs.slice(0,recordLimit))}${rs.length>recordLimit?btn('再显示 '+Math.min(80,rs.length-recordLimit)+' 条','more-records','secondary full'):''}`;}
function chartHTML(items){const max=Math.max(...items.map(i=>i.amountCents),1),w=600,h=175,left=42,right=8,plot=w-left-right,n=items.length,step=plot/n,bw=Math.min(step*.65,36);const ticks=[max,max/2,0];return `<svg class="chart" viewBox="0 0 ${w} ${h+27}" role="img" aria-label="充电费用趋势，详细数值见下方表格">${ticks.map(v=>`<path d="M${left} ${15+(1-v/max)*(h-35)}H${w-right}" stroke="#e8edf5" stroke-dasharray="3 4"/><text x="${left-7}" y="${19+(1-v/max)*(h-35)}" text-anchor="end">${(v/100).toFixed(0)}</text>`).join('')}${items.map((i,k)=>{const bh=i.amountCents/max*(h-35),x=left+k*step+(step-bw)/2,y=h-20-bh;return `<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="${Math.min(4,bw/2)}" fill="${k===n-1?'#2760ec':'#8eaff8'}"><title>${H(i.label)}：${L.money(i.amountCents)}元，${L.energySummary(i)}度，${i.count}条费用</title></rect>${n<=12||k%Math.ceil(n/7)===0||k===n-1?`<text class="chart-label" x="${left+k*step+step/2}" y="${h+4}" text-anchor="middle">${H(i.label)}</text>`:''}`;}).join('')}</svg>`;}
function comparisonHTML(c){
 const names={day:'上日',week:'上周',month:'上月',quarter:'上季',year:'上年'},incomplete=c.currentPeriod.start<=L.todayTime().slice(0,10)&&c.currentPeriod.end>L.todayTime().slice(0,10);
 const value=(key,n)=>n==null?'—':key==='amount'?'¥'+L.money(n):key==='energy'?L.energy(n)+' 度':key==='price'?Number(n).toFixed(4)+' 元/度':n+' 条';
 return `<section class="card comparison-card" aria-label="环比变化"><div class="caption-line"><h3>环比变化</h3><span class="small muted">对比${names[grain]}</span></div><p class="comparison-period small muted">${H(c.previousPeriod.label)}</p><div class="comparison-grid">${c.metrics.map(m=>`<div class="comparison-metric"><span>${({amount:'充电费用',energy:'已知电量',price:'有电量均价',count:'费用条目'})[m.key]}</span><strong class="change ${m.direction}" data-change="${m.key}">${m.direction==='up'?'↑ ':m.direction==='down'?'↓ ':''}${m.label}</strong><small>上期 ${value(m.key,m.before)}</small></div>`).join('')}</div><p class="small muted comparison-note">${incomplete?'本期尚未结束，按已记费用对比上一完整周期。':'按相邻完整自然周期及相同用途筛选比较。'}红色表示增加，绿色表示减少；上期无记录或电量缺失时不计算对应比例。</p></section>`;
}
function stats(){
 const p=L.period(anchor,grain),rs=L.filter(state.records,{category,start:p.start,until:p.end,grain}),s=L.sum(rs),items=L.series(rs,p,grain);
 const coarse=L.sum(L.filter(state.records,{category,start:L.period(anchor,'month').start,until:L.period(anchor,'month').end}).filter(r=>L.precision(r)==='month'));
 const stations=new Map();rs.filter(r=>r.station&&r.recordKind!=='trip_expense_summary').forEach(r=>{if(!stations.has(r.station))stations.set(r.station,[]);stations.get(r.station).push(r);});
 const top=[...stations].map(([name,rows])=>({name,...L.sum(rows)})).sort((a,b)=>b.amountCents-a.amountCents).slice(0,5);
 return `${heading('用电统计','开销的变化，一眼看清。','export','download')}${tabs([['day','日'],['week','周'],['month','月'],['quarter','季'],['year','年']],grain,'grain')}<div class="period-control"><button class="icon-button" data-action="prev-period" aria-label="上一时段">${icon('left')}</button><strong>${H(p.label)}</strong><button class="icon-button" data-action="next-period" aria-label="下一时段">${icon('arrow')}</button></div>${categoryTabs()}${['day','week'].includes(grain)&&coarse.count?`<div class="notice precision-notice">本月另有 ${coarse.count} 条仅记月份的费用，共 ¥${L.money(coarse.amountCents)}。请切换月、季或年查看，不分摊到日或周。</div>`:''}<section class="card"><div class="caption-line"><span class="muted medium">充电费用</span>${btn('回到当前','current-period','text-button')}</div><div class="summary-main"><b>¥${L.money(s.amountCents)}</b><span>${s.count} 条费用</span></div><div class="metric-trio"><div><b>${L.energySummary(s)}</b><span>已知电量 / 度</span></div><div><b>${L.priceText(s,4)}</b><span>有电量均价 / 元每度</span></div><div><b>${L.money(s.parkingCents)}</b><span>另付停车费 / 元</span></div></div><p class="small muted metric-note">${H(L.coverage(s))}</p>${chartHTML(items)}<div class="chart-caption"><span>费用趋势 · 元</span><span>${grain==='month'&&coarse.count?'月份合计单列':'按已知日期归属'}</span></div></section>${comparisonHTML(L.comparison(state.records,anchor,grain,category))}<section class="card"><h3>日常与差旅</h3>${[['daily','日常用电'],['business','差旅用电']].filter(([c])=>category==='all'||category===c).map(([c,name])=>{const t=L.sum(rs.filter(r=>r.category===c));return `<div class="station-row"><div><strong>${name}</strong><span>${t.count} 条费用 · ${t.tripSummaryCount} 条行程合计</span></div><strong class="number">¥${L.money(t.amountCents)}</strong></div>`;}).join('')}<div class="small muted">综合支出（含另付停车费）：¥${L.money(s.amountCents+s.parkingCents)}</div></section><div class="section-heading"><h2>充电地点</h2><span class="small muted">已记地点 · 按费用排序</span></div><section class="card">${top.length?top.map(t=>`<div class="station-row"><div><strong>${H(t.name)}</strong><span>${t.count} 条费用 · 有电量均价 ${L.priceText(t,4)} 元/度</span></div><strong class="number">¥${L.money(t.amountCents)}</strong></div>`).join(''):`<p class="muted medium">补充充电地点后，可在这里查看各站费用。</p>`}</section><details><summary>查看趋势数据明细</summary><div class="table-wrap"><table><thead><tr><th>时段</th><th>费用条目</th><th>已知度数</th><th>费用/元</th></tr></thead><tbody>${items.map(i=>`<tr><td>${H(i.label)}</td><td>${i.count}</td><td>${L.energySummary(i)}</td><td>${L.money(i.amountCents)}</td></tr>`).join('')}</tbody></table></div></details><p class="small muted">行程合计可能包含多次充电，费用条目不等于充电次数。补录行程明细前，请先移除对应合计，避免重复计算。</p>`;
}
let tariffMonth=Number(L.todayTime().slice(5,7)),tariffRegion=0;
function monthSchedule(region){return (region.seasons||[]).find(s=>s.months.includes(tariffMonth));}
function timeIntervals(str){return String(str||'').split('、').map(x=>x.trim()).filter(x=>/^\d\d:\d\d[—-]\d\d:\d\d$/.test(x)).flatMap(x=>{const [a,b]=x.split(/[—-]/).map(t=>Number(t.slice(0,2))*60+Number(t.slice(3)));return b>a?[[a,b]]:[[a,1440],[0,b]];});}
function tariffBar(s){const colors={flat:'#cad4e7',valley:'#32a794',peak:'#eea952',sharp:'#d96e72',deep:'#138f88'};const sections=[['flat','00:00—24:00'],['valley',s.valley],['peak',s.peak],['sharp',s.sharp],['deep',s.deep]];return `<svg class="tariff-bar" viewBox="0 0 600 43" role="img" aria-label="一天24小时峰谷时段">${sections.flatMap(([k,str])=>timeIntervals(str).map(([a,b])=>`<rect x="${a/1440*600}" y="6" width="${(b-a)/1440*600}" height="28" fill="${colors[k]}"/>`)).join('')}</svg><div class="tariff-hours"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>24:00</span></div>`;}
function tariffs(){const data=window.TARIFFS,province=data.provinces.find(p=>p.name===state.settings.province)||data.provinces[0],region=province.regions[Math.min(tariffRegion,province.regions.length-1)],s=monthSchedule(region),ready=!!s;return `${heading('峰谷电价参考','远行前，先了解当地时段。','', '')}<div class="notice">公用站实际收费由站点公示的电费、服务费与优惠决定。这里提供政策时段参考，选站时请核对充电订单页。</div><div class="province-controls"><label><span class="field-label">省级地区</span><select id="tariff-province">${data.provinces.map(p=>`<option ${p.name===province.name?'selected':''}>${H(p.name)}</option>`).join('')}</select></label><label><span class="field-label">参考月份</span><select id="tariff-month">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${i+1===tariffMonth?'selected':''}>${i+1}月</option>`).join('')}</select></label></div>${province.regions.length>1?`<label class="field"><span class="field-label">供电区域 / 计价类型</span><select id="tariff-region">${province.regions.map((r,i)=>`<option value="${i}" ${r===region?'selected':''}>${H(r.name)}</option>`).join('')}</select></label>`:''}<section class="card"><div class="tariff-title"><h2>${H(province.name)}${province.regions.length>1?' · '+H(region.name):''}</h2><span class="badge ${ready&&region.verified!==false?'daily':'warning'}">${ready?(region.verified===false?'转载待核':'政策资料'):'待核实'}</span></div><p class="small muted">${H(region.scope)}</p>${ready?`${tariffBar(s)}<div class="tariff-legend"><span><i class="legend-dot valley"></i>低谷</span><span><i class="legend-dot flat"></i>平段</span><span><i class="legend-dot peak"></i>高峰</span><span><i class="legend-dot sharp"></i>尖峰</span>${s.deep?'<span><i class="legend-dot deep"></i>深谷</span>':''}</div>${[['低谷',s.valley],['高峰',s.peak],['尖峰',s.sharp],['深谷',s.deep]].filter(([,v])=>v).map(([k,v])=>`<div class="time-row"><span class="time-name">${k}</span><span class="time-value">${H(v)}</span></div>`).join('')}<div class="time-row"><span class="time-name">平段</span><span class="small">${H(s.flat||'其余时段')}</span></div>${s.note?`<p class="notice warning no-bottom">${H(s.note)}</p>`:''}`:`<div class="empty"><div class="empty-icon">${icon('clock')}</div><h3>暂未收录可用时段</h3><p>${H(region.reason||'该地区最新政策需要进一步核实，请查看官方资料与站点公示。')}</p></div>`}<div class="source-info">${H(region.note||'')}<br>资料适用起点：${H(region.effective||'待核实')}<br>检索日期：${data.checkedAt} · 不自动联网更新<br>${region.url?`<a href="${H(region.url)}" target="_blank" rel="noopener">${icon('link')}${region.verified===false?'查看转载来源':'查看官方来源'}</a>`:''}${region.policy?`<div>${H(region.policy)}</div>`:''}</div></section><div class="notice warning">全国 ${data.provinces.length} 个省级地区索引已收录。资料按文件适用范围展示；转载资料已单独标为待核；未收录的区域不填写推测时段。部分地区已改用市场交易分时价格，省内也可能存在不同供电区域。</div><div class="section-heading"><h2>出行充电小贴士</h2></div><section class="card about-list"><p>比较订单中的每度综合价格，而不仅是电费。服务费、停车费、占位费和会员优惠都可能影响最终开销。</p><p>跨越峰谷边界充电时，计费可能按各时段电量或平台规则分段结算。出发前查看具体站点当日价格。</p><p class="no-bottom">补能完成后，勾选“差旅用电”并填写行程名，后续报销和按行程整理会更方便。</p></section>`;}
function menu(label,sub,action,i){return `<button class="menu-item" data-action="${action}"><span class="menu-icon">${icon(i)}</span><span class="menu-copy"><strong>${H(label)}</strong><span>${H(sub)}</span></span>${icon('arrow')}</button>`;}
function profile(){const s=L.sum(state.records);return `${heading('我的手账','数据在自己手里。','', '')}<section class="card vehicle-card"><div class="vehicle-icon">${icon('car')}</div><div><strong>${H(state.settings.vehicle)}</strong><p>累计 ${s.count} 条费用 · ${s.tripSummaryCount} 条行程合计</p></div></section><div class="list-menu">${menu('导出 Markdown','整理明细和统计，供外部 AI 分析','export','download')}${menu('备份全部数据','保存 JSON 备份，可迁移至新手机','backup','shield')}${menu('追加导入历史费用','导入 JSON，保留当前记录和设置','import','upload')}${menu('恢复数据备份','先核对内容，再恢复本地手账','restore','upload')}</div><div class="list-menu">${menu('车辆与预算','车辆名称、月度充电预算和定位偏好','settings','settings')}${menu('回收站',state.trash.length+' 条已删除记录，可随时恢复','recycle','trash')}${menu('使用说明与隐私','统计口径、定位说明和数据保存','about','info')}</div><section class="card budget-row"><div class="menu-icon">${icon('shield')}</div><div class="budget-text"><h3>本地保存，随时带走</h3><p>充电记录不上传，不内置 AI。换机或卸载前，请导出一份完整备份。</p></div></section><div class="app-footer">充电手账 · v1.3.2<br>为每一次出发，留下清晰记录。</div>`;}
const navigation=[['home','home','首页'],['records','list','明细'],['stats','chart','统计'],['tariffs','clock','电价'],['profile','user','我的']];
let lastScreen='',focusBeforeSheet=null,pendingImport=null,fileMode='restore';
function reducedMotion(){return state.settings.motion==='reduced'||matchMedia('(prefers-reduced-motion: reduce)').matches;}
function animate(el,frames,options){if(!reducedMotion()&&el?.animate)return el.animate(frames,options);}
function pageDescriptor(name){
 const filters=name==='records'?[category,listSearch,listStart,listEnd,recordLimit]:name==='stats'?[category,grain,anchor]:name==='tariffs'?[tariffMonth,tariffRegion,state.settings.province]:[];
 return {signature:JSON.stringify([dataRevision,L.todayTime().slice(0,10),storageError,...filters]),html:()=>`${demo?'<div class="demo-banner">演示模式 · 独立样例，不影响正式记录</div>':''}${storageError?`<div class="notice warning">${H(storageError)}</div>`:''}${({home,records:recordsPage,stats,tariffs,profile})[name]()}`};
}
function syncNativeBack(){if(native&&typeof native.setBackHandling==='function')native.setBackHandling(screen!=='home'||!!modal||Interactions.hasPicker());}
function render(){
 document.documentElement.dataset.motion=reducedMotion()?'reduced':'full';
 const app=document.getElementById('app');
 if(!document.getElementById('page-content'))app.innerHTML=`<main class="shell"><div id="page-content"></div></main><nav class="nav" aria-label="主导航">${navigation.map(([v,i,t])=>`<button class="nav-button" data-action="navigate" data-value="${v}">${icon(i)}<span>${t}</span></button>`).join('')}</nav><button id="records-add" class="page-add" data-action="new" aria-label="记录充电" hidden>${icon('plus')}</button>`;
 Interactions.render();document.getElementById('records-add').hidden=screen!=='records';syncNativeBack();
}
let sheetAnimation=null,scrimAnimation=null,sheetGeneration=0;
function openSheet(title,content){
 const root=document.getElementById('overlay-root');let backdrop=root.querySelector('.modal-backdrop'),existing=backdrop?.querySelector('.sheet');
 const opening=!backdrop||backdrop.hidden||backdrop.dataset.closing==='true';const token=++sheetGeneration;
 sheetAnimation?.cancel();scrimAnimation?.cancel();sheetAnimation=null;
 if(!existing){
  root.append(Interactions.fragment(`<div class="modal-backdrop" hidden><div class="sheet-scrim"></div><section class="sheet" role="dialog" aria-modal="true" aria-label="${H(title)}" tabindex="-1"><div class="sheet-handle" aria-hidden="true"></div><header class="sheet-header"><h2>${H(title)}</h2><button class="icon-button" data-action="close" aria-label="关闭">${icon('close')}</button></header><div class="sheet-body"></div></section></div>`));
  backdrop=root.firstElementChild;existing=backdrop.querySelector('.sheet');
 }
 const changed=existing.getAttribute('aria-label')!==title;
 existing.setAttribute('aria-label',title);existing.querySelector('.sheet-header h2').textContent=title;
 Interactions.patchChildren(existing.querySelector('.sheet-body'),Interactions.fragment(content));
 backdrop.dataset.closing='false';backdrop.style.pointerEvents='';
 if(opening){
  focusBeforeSheet=document.activeElement;existing.scrollTop=0;
  backdrop.hidden=false;
  sheetAnimation=animate(existing,[{transform:'translate3d(0,44px,0)',opacity:0},{transform:'translate3d(0,0,0)',opacity:1}],{duration:320,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'});
  scrimAnimation=animate(backdrop.querySelector('.sheet-scrim'),[{opacity:0},{opacity:1}],{duration:260,fill:'both'});
  const ready=()=>{if(token===sheetGeneration&&!existing.contains(document.activeElement))existing.focus({preventScroll:true});};
  if(sheetAnimation)sheetAnimation.finished.then(ready).catch(()=>{});else ready();
 }else if(changed){existing.scrollTop=0;existing.focus({preventScroll:true});}
 document.getElementById('app').inert=true;document.querySelector('.nav').inert=true;syncNativeBack();
}
function closeSheet(){
 Interactions.closePicker();modal='';editId=null;formLocation=null;locateToken++;pendingRestore=null;pendingImport=null;syncNativeBack();
 const backdrop=document.querySelector('.modal-backdrop');if(!backdrop||backdrop.hidden)return;
 const token=++sheetGeneration;sheetAnimation?.cancel();scrimAnimation?.cancel();backdrop.dataset.closing='true';backdrop.style.pointerEvents='none';
 const sheet=backdrop.querySelector('.sheet');
 const cleanup=()=>{if(token!==sheetGeneration)return;backdrop.hidden=true;backdrop.dataset.closing='false';document.getElementById('app').inert=false;document.querySelector('.nav').inert=false;if(focusBeforeSheet?.isConnected)focusBeforeSheet.focus({preventScroll:true});Interactions.patchChildren(sheet.querySelector('.sheet-body'),Interactions.fragment(''));sheetAnimation?.cancel();scrimAnimation?.cancel();sheetAnimation=null;scrimAnimation=null;};
 sheetAnimation=animate(sheet,[{transform:'translate3d(0,0,0)',opacity:1},{transform:'translate3d(0,32px,0)',opacity:0}],{duration:220,easing:'cubic-bezier(.4,0,1,1)',fill:'both'});
 scrimAnimation=animate(backdrop.querySelector('.sheet-scrim'),[{opacity:1},{opacity:0}],{duration:220,fill:'both'});
 if(sheetAnimation)sheetAnimation.finished.then(cleanup).catch(()=>{});else cleanup();
}
function closeRequested(){if(modal==='record'&&formDirty){openDiscard();return;}closeSheet();}
let formDirty=false,discardPending=false;
function openDiscard(){if(discardPending)return;discardPending=true;const sheet=document.querySelector('.sheet');const bar=document.createElement('div');bar.className='notice warning';bar.id='discard-notice';bar.innerHTML=`未保存的内容会丢失。<div class="sheet-actions">${btn('继续填写','keep-edit','outline')}${btn('放弃修改','discard','secondary')}</div>`;sheet.insertBefore(bar,sheet.children[1]);bar.scrollIntoView({block:'center'});}
function formField(label,name,value,type='text',placeholder='',hint=''){return `<div class="field"><label class="field-label" for="f-${name}">${label}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${H(value??'')}" placeholder="${H(placeholder)}" ${type==='number'?'inputmode="decimal" step="any"':''}>${hint?`<div class="field-hint">${H(hint)}</div>`:''}</div>`;}
function newRecord(id){
 editId=id||null;const r=id?state.records.find(r=>r.id===id):{};if(!r){toast('记录不存在');return;}
 formDirty=false;discardPending=false;formLocation=r.location||null;modal='record';
 const precision=id?L.precision(r):'minute',value=id?(r.time||r.date||r.monthKey):L.todayTime(),stations=[...new Set(L.filter(state.records).map(r=>r.station).filter(Boolean))];
 openSheet(id?'编辑费用记录':'记录充电费用',`<form id="record-form" novalidate><div class="form-error" id="form-error" role="alert"></div><div class="notice form-intro">电量、地点可以留空。只记得月份时，选择“仅月份”。</div><div class="field-row temporal-row"><label class="field"><span class="field-label">时间精度</span><select id="f-precision" name="precision">${[['minute','完整时间'],['day','仅日期'],['month','仅月份']].map(([v,t])=>`<option value="${v}" ${v===precision?'selected':''}>${t}</option>`).join('')}</select></label>${formField('日期 / 月份','time',value,{minute:'datetime-local',day:'date',month:'month'}[precision])}</div><label class="field type-field"><span class="field-label">记录类型</span><select id="f-kind" name="recordKind"><option value="charging_expense" ${r.recordKind!=='trip_expense_summary'?'selected':''}>单笔充电费用</option><option value="trip_expense_summary" ${r.recordKind==='trip_expense_summary'?'selected':''}>差旅行程合计（多次充电）</option></select></label><div class="field-row">${formField('计费电量 <span class="label-unit">可选 · kWh</span>','energy',r.energyMilli!=null?L.energy(r.energyMilli):'','number','未记录可留空')}${formField('实际费用 <span class="label-unit">必填 · 元</span>','amount',r.amountCents!=null?L.money(r.amountCents):'','number','例如 32.80')}</div><div class="price-preview"><span>有电量时计算单价</span><div><strong id="price-preview">—</strong> 元/度</div></div><div class="field"><span class="field-label">用电用途</span><div class="choice-row">${[['daily','car','日常用电'],['business','bag','差旅用电']].map(([v,i,t])=>`<label class="choice"><input name="category" type="radio" value="${v}" ${(r.category||'daily')===v?'checked':''}><span>${icon(i)}${t}</span></label>`).join('')}</div></div><div class="field"><label class="field-label" for="f-station">充电地点 <span class="label-unit">可选</span></label><div class="location-line"><input class="input" id="f-station" name="station" list="station-options" maxlength="160" placeholder="站名可稍后补充" value="${H(r.station||'')}"><button type="button" class="secondary" data-action="locate" id="locate-button">${icon('locate')}定位</button></div><datalist id="station-options">${stations.map(s=>`<option value="${H(s)}">`).join('')}</datalist><div class="field-hint" id="location-status">附近地址供参考，请核对充电站。</div></div>${formField('行程名称 <span class="label-unit">可选</span>','trip',r.trip||'','text','例如：武汉-北京')}<div class="field"><label class="field-label" for="f-note">备注 <span class="label-unit">可选</span></label><textarea id="f-note" name="note" maxlength="2000" placeholder="优惠、充电体验，或需要记下的事">${H(r.note||'')}</textarea></div><details><summary>更多详情：运营商、电量、停车费、里程</summary>${formField('运营商','operator',r.operator||'','text','例如：国家电网、星星充电')}${formField('地址','address',r.address||'','text','定位后自动补充，可修改')}<div class="field-row">${formField('充电前电量 <span class="label-unit">%</span>','socStart',r.socStart??'','number','20')}${formField('充电后电量 <span class="label-unit">%</span>','socEnd',r.socEnd??'','number','80')}</div><div class="field-row">${formField('充电时长 <span class="label-unit">分钟</span>','duration',r.duration??'','number','45')}${formField('表显里程 <span class="label-unit">km</span>','odometer',r.odometer??'','number','12800')}</div>${formField('另付停车费 <span class="label-unit">元</span>','parking',r.parkingCents!=null?L.money(r.parkingCents):'','number','未记录可留空','独立计入综合支出，不加入充电单价。')}</details><button type="submit" class="primary full">${icon('check')}${id?'保存修改':'保存费用记录'}</button><p class="privacy-line">保存在本机 · 随时补齐信息</p></form>`);
 updatePrice();if(!id&&state.settings.autoLocate)locate();
}
function updatePrice(){const a=document.getElementById('f-amount'),e=document.getElementById('f-energy'),out=document.getElementById('price-preview');if(!out)return;try{const cents=L.decimal(a.value,2,'金额'),milli=L.decimal(e.value,3,'度数');out.textContent=milli>0?(cents*10/milli).toFixed(4):'—';}catch(_){out.textContent='—';}}
function readForm(){
 const fd=new FormData(document.getElementById('record-form')),get=k=>String(fd.get(k)||'').trim(),optional=(k,integer=false)=>{const v=get(k);if(!v)return null;if(!/^\d+(\.\d+)?$/.test(v))throw new Error('请检查可选数值字段');const n=Number(v);if(integer&&!Number.isInteger(n))throw new Error('电量百分比与充电时长请填整数');return n;};
 const precision=get('precision'),value=get('time'),old=editId?state.records.find(r=>r.id===editId):{};
 const r={...old,id:editId||('r_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10)),time:precision==='minute'?value:null,datePrecision:precision,date:precision==='day'?value:null,monthKey:value.slice(0,7),timezone:'Asia/Shanghai',recordKind:get('recordKind'),energyMilli:get('energy')?L.decimal(get('energy'),3,'计费电量'):null,amountCents:L.decimal(get('amount'),2,'实际费用'),category:get('category'),station:get('station')||null,address:get('address'),note:get('note'),trip:get('trip'),operator:get('operator'),socStart:optional('socStart',true),socEnd:optional('socEnd',true),duration:optional('duration',true),odometer:optional('odometer'),parkingCents:get('parking')?L.decimal(get('parking'),2,'停车费'):null,location:formLocation};
 return L.validateRecord(r);
}
function saveRecord(){try{const r=readForm();if(!editId&&r.time&&state.records.some(x=>x.time&&L.fingerprint(x)===L.fingerprint(r)))throw new Error('已有相同内容的记录，请先检查明细');if(mutate(s=>{const i=s.records.findIndex(x=>x.id===r.id);if(i<0)s.records.push(r);else s.records[i]=r;})){closeSheet();render();toast('充电记录已保存');}}catch(e){const el=document.getElementById('form-error');el.textContent=e.message;el.scrollIntoView({block:'center'});}}
function detail(id){
 const r=state.records.find(r=>r.id===id);if(!r){toast('记录不存在');return;}modal='detail';
 openSheet('费用详情',`<div class="badge ${r.category}">${L.categories[r.category]} · ${r.recordKind==='trip_expense_summary'?'行程合计':'单笔费用'}</div><div class="detail-number">¥${L.money(r.amountCents)}</div>${r.recordKind==='trip_expense_summary'?'<div class="notice">这是多次充电的行程合计。补录明细前请先移除本条，避免重复计算。</div>':''}<section class="card detail-grid">${[['日期 / 月份',L.displayDate(r)],['充电地点',r.station||'未记录'],['计费电量',r.energyMilli==null?'未记录':L.energy(r.energyMilli)+' kWh'],['综合单价',r.energyMilli==null?'缺电量，暂不计算':L.priceText(r,4)+' 元/度'],['运营商',r.operator||'未记录'],['行程',r.trip||'未记录'],['电量变化',r.socStart!=null||r.socEnd!=null?`${r.socStart??'—'}% → ${r.socEnd??'—'}%`:'未记录'],['充电时长',r.duration!=null?r.duration+' 分钟':'未记录'],['表显里程',r.odometer!=null?r.odometer+' km':'未记录'],['另付停车费',r.parkingCents!=null?'¥'+L.money(r.parkingCents):'未记录']].map(([k,v])=>`<div><span>${k}</span><strong>${H(v)}</strong></div>`).join('')}</section>${r.address?`<section class="card"><h3>地址</h3><p class="detail-note">${H(r.address)}</p></section>`:''}<section class="card"><h3>备注</h3><p class="detail-note">${H(r.note||'暂无备注')}</p></section><div class="sheet-actions"><button class="outline danger" data-action="delete" data-id="${H(id)}">${icon('trash')}移入回收站</button><button class="primary" data-action="edit" data-id="${H(id)}">${icon('edit')}编辑记录</button></div>`);
}
function deleteRecord(id){if(mutate(s=>{const i=s.records.findIndex(r=>r.id===id);if(i>=0){s.trash.push({...s.records[i],deletedAt:L.todayTime()});s.records.splice(i,1);}})){closeSheet();render();toast('已移入回收站，可在“我的”中恢复');}}
function recycle(){modal='recycle';openSheet('回收站',`<p class="muted medium">记录保留在本机，恢复后重新计入统计。</p>${state.trash.length?L.filter(state.trash).map(r=>`<div class="recycle-row"><div><strong>${H(recordTitle(r))}</strong><span>${H(L.displayDate(r))} · ¥${L.money(r.amountCents)}</span></div><button class="secondary" data-action="recover" data-id="${H(r.id)}">恢复</button></div>`).join(''):empty('回收站是空的','删除的充电记录会保留在这里。','','')}`);}
function locate(){const token=++locateToken;const b=document.getElementById('locate-button'),label=document.getElementById('location-status');if(!b)return;b.disabled=true;label.textContent='正在获取位置，请保持定位开启…';if(native){native.locate(String(token));}else if(navigator.geolocation){navigator.geolocation.getCurrentPosition(p=>locationResult({token:String(token),lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,address:''}),e=>locationResult({token:String(token),error:e.code===1?'定位权限未开启，请手动填写地点。':'定位未成功，请重试或手动填写地点。'}),{enableHighAccuracy:true,timeout:25000,maximumAge:0});}else locationResult({token:String(token),error:'浏览器不支持定位，请在安卓应用中使用。'});setTimeout(()=>{if(token===locateToken&&document.getElementById('locate-button')?.disabled)locationResult({token:String(token),error:'定位超时，请手动填写或重试。'});},47000);}
function locationResult(info){if(typeof info==='string')try{info=JSON.parse(info);}catch(_){return;}if(modal!=='record'||String(locateToken)!==String(info.token))return;const label=document.getElementById('location-status'),b=document.getElementById('locate-button');b.disabled=false;if(info.error){label.textContent=info.error;return;}formLocation={lat:info.lat,lng:info.lng,accuracy:info.accuracy};const known=state.records.filter(r=>r.station&&r.location&&info.accuracy<=100).map(r=>({r,d:L.distance(formLocation,r.location)})).filter(x=>x.d<=150).sort((a,b)=>a.d-b.d)[0];const station=document.getElementById('f-station'),address=document.getElementById('f-address');if(known){if(!station.value.trim())station.value=known.r.station;address.value=info.address||known.r.address||'';label.textContent=`匹配附近已记录地点（约 ${Math.round(known.d)} 米），请核对站名。`;}else if(info.address){if(!station.value.trim())station.value=info.address.slice(0,160);address.value=info.address.slice(0,300);label.textContent=`已获取附近地址（精度约 ${Math.round(info.accuracy)} 米），请确认具体充电站名。`;}else label.textContent=`位置已获取（精度约 ${Math.round(info.accuracy)} 米），地址暂不可用，请手动填写站名。`;formDirty=true;}
window.onNativeLocation=locationResult;
function exportSheet(){modal='export';const defaultStart=screen==='stats'?L.period(anchor,grain).start:(screen==='records'?listStart:''),defaultEnd=screen==='stats'?L.shift(L.period(anchor,grain).end,-1):(screen==='records'?listEnd:'');openSheet('导出 Markdown',`<p class="muted medium">一份文件，包含充电明细、分类总览与日周月季年统计，可复制给外部 AI。</p><div class="field"><label class="field-label" for="export-category">用电用途</label><select id="export-category">${[['all','全部用电'],['daily','日常用电'],['business','差旅用电']].map(([v,t])=>`<option value="${v}" ${category===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="date-range"><label>开始日期<input class="input" type="date" id="export-start" value="${defaultStart}"></label><label>结束日期<input class="input" type="date" id="export-end" value="${defaultEnd}"></label></div><p class="field-hint">留空导出全部日期。明细列表中的关键词搜索不限制本次导出。</p><label class="check-row"><input id="export-private" type="checkbox" checked>包含地点、行程与备注（不导出精确坐标）</label><div class="export-summary" id="export-summary"></div><details><summary>预览导出内容</summary><pre class="markdown-preview" id="markdown-preview"></pre></details><button class="primary full" data-action="download-md">${icon('download')}导出 .md 文件</button><div class="sheet-actions">${btn('复制全文','copy-md','outline','copy')}${native?btn('分享文件','share-md','outline','share'):''}</div>`);updateExport();}
function updateExport(){if(modal!=='export')return;const c=document.getElementById('export-category').value,a=document.getElementById('export-start').value,b=document.getElementById('export-end').value,n=document.getElementById('export-private').checked,invalid=a&&b&&a>b;exportRecords=invalid?[]:L.filter(state.records,{category:c,start:a,end:b});exportContent=L.markdown(exportRecords,{vehicle:state.settings.vehicle,includePrivate:n,scope:(c==='all'?'全部用电':L.categories[c])+' · '+(a||'最早')+' 至 '+(b||'最新')});const s=L.sum(exportRecords);document.getElementById('export-summary').innerHTML=invalid?'开始日期不能晚于结束日期。':`将导出 <strong>${s.count}</strong> 条费用<br>充电费用 ¥${L.money(s.amountCents)} · ${L.energySummary(s)} 度`;document.getElementById('markdown-preview').textContent=exportContent;document.querySelector('[data-action="download-md"]').disabled=!!invalid;}
function download(content,name,mime){if(native){native.exportFile(name,mime,content);return;}const url=URL.createObjectURL(new Blob([content],{type:mime+';charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),20000);toast('已发起文件下载');}
window.onNativeExport=message=>toast(message);
async function copyMD(){try{if(native){if(native.copy(exportContent))toast('Markdown 已复制');else toast('内容过长或复制未成功，请导出文件。');}else{await navigator.clipboard.writeText(exportContent);toast('Markdown 已复制');}}catch(_){toast('复制未成功，请导出文件后复制。');}}
function backup(){download(JSON.stringify(state,null,2),'充电手账_完整备份_'+L.todayTime().slice(0,10)+'.json','application/json');}
function receiveBackup(raw){try{if(raw.length>20000000)throw new Error('备份过大');const s=L.validateState(JSON.parse(raw));pendingRestore=s;modal='restore';openSheet('核对备份内容',`<section class="card"><h3>${H(s.settings.vehicle)}</h3><div class="export-summary"><strong>${s.records.length}</strong> 条充电记录 · ${s.trash.length} 条回收站记录<br>充电费用 ¥${L.money(L.sum(s.records).amountCents)}<br>备份更新：${H(s.updatedAt||'未记录')}</div><p class="muted medium">恢复将替换当前 ${state.records.length} 条记录、回收站与设置。建议先保存当前完整备份。</p></section><div class="sheet-actions">${btn('先备份当前数据','backup','outline','download')}${btn('确认恢复','confirm-restore','primary','check')}</div>`);}catch(e){toast('恢复未执行：'+e.message);}}
function chooseFile(mode){fileMode=mode;if(native)native.importFile();else document.getElementById('backup-file').click();}
function importSheet(){modal='import-info';openSheet('追加导入历史费用',`<section class="card"><div class="import-emblem">${icon('upload')}</div><h3>把过去的费用，也记下来。</h3><p class="muted medium import-copy">选择历史费用 JSON，核对后追加到现有手账。也可从完整备份中追加费用记录。</p><div class="import-rules"><p>${icon('check')}保留已有记录、回收站和设置</p><p>${icon('check')}电量、地点可以为空，日期可只到月份</p><p>${icon('check')}相同编号与内容跳过，不重复导入</p></div><p class="field-hint">行程合计和其明细不要同时导入，以免费用重复计算。</p></section>${btn('选择 JSON 文件','choose-import','primary full','upload')}`);}
function receiveFile(raw){const mode=fileMode;fileMode='restore';if(mode==='append')receiveImport(raw);else receiveBackup(raw);}
function receiveImport(raw){try{
 if(raw.length>20000000)throw new Error('文件过大');const records=L.parseImport(raw),plan=L.planImport(state,records),s=L.sum(plan.added);pendingImport=records;modal='import-preview';
 openSheet('核对追加导入',`<section class="card"><div class="export-summary"><strong>${plan.total}</strong> 条来源费用<br>新增 ${plan.added.length} 条 · 跳过相同编号与内容 ${plan.skipped} 条<br>新增费用 ¥${L.money(s.amountCents)}<br>其中行程合计 ${s.tripSummaryCount} 条</div><p class="muted medium">当前 ${state.records.length} 条费用、回收站和设置都会保留。文件中缺失的电量保持未知，仅记月份的费用不拆分到某天。</p><p class="field-hint">${H(L.coverage(s))}</p></section><div class="sheet-actions">${btn('取消','close','outline')}${btn(plan.added.length?'确认追加导入':'全部已存在','confirm-import','primary','check')}</div>`);
 document.querySelector('[data-action="confirm-import"]').disabled=!plan.added.length;
}catch(e){toast('追加导入未执行：'+e.message);}}
function confirmImport(){if(!pendingImport)return;try{const plan=L.planImport(state,pendingImport);if(mutate(s=>plan.added.forEach(r=>s.records.push(r)))){closeSheet();screen='records';render();toast(`已追加 ${plan.added.length} 条费用，原有数据已保留`);}}catch(e){toast('追加导入未执行：'+e.message);}}
window.onNativeImport=receiveFile;
window.onNativeError=message=>toast(message);
function settings(){modal='settings';openSheet('车辆与预算',`<form id="settings-form" novalidate>${formField('车辆名称','vehicle',state.settings.vehicle,'text','我的新能源汽车')}${formField('月度充电预算 <span class="label-unit">元</span>','budget',L.money(state.settings.budgetCents),'number','500.00','用于跟踪充电支出，停车费另计。设置为0可关闭预算。')}<label class="check-row"><input type="checkbox" id="auto-locate" ${state.settings.autoLocate?'checked':''}>新建记录时自动获取附近地址</label><label class="field motion-field"><span class="field-label">界面动画</span><select id="motion-mode"><option value="system" ${state.settings.motion!=='reduced'?'selected':''}>跟随系统 · 平滑动画</option><option value="reduced" ${state.settings.motion==='reduced'?'selected':''}>减少动画</option></select></label><p class="notice">仅在记录充电时申请位置，不在后台追踪。地址识别取决于手机定位和系统地理编码服务。</p><div class="form-error" id="settings-error" role="alert"></div><button type="submit" class="primary full">保存设置</button></form>`);}
function about(){modal='about';openSheet('使用说明与隐私',`<div class="about-list"><h3>如何记录</h3><p>填写实际费用并选择日常或差旅，日期可只记到月份。电量和地点可留空，有电量时计算单价；停车费、运营商、行程、电量与里程可按需补充。</p><h3>统计与精度</h3><p>金额支持2位小数，电量支持3位小数，以整数“分”和“千分之一度”保存。缺电量的费用不参与均价，均价仅使用有电量的费用和电量，显示4位小数。首页为北京时间当前月，周从周一开始，季度为自然季度。</p><h3>自动识别地点</h3><p>定位后优先匹配150米内已记录的地点，否则使用系统返回的附近地址。多个充电站可能相邻，定位结果需要核对。系统地理编码可能需要联网；拒绝权限或离线时可手动填写。</p><h3>数据保存与备份</h3><p>安卓端保存在应用私有空间；不设置登录，不上传充电记录，不调用 AI。文件导出通过系统文件选择器，分享通过系统分享面板。卸载、清除应用数据或手机损坏可能导致本地记录丢失，请定期导出 JSON 完整备份。Markdown 用于阅读与分析，JSON 支持追加导入与完整恢复。仅记月份的合计参加月、季、年统计，不分摊到日或周。</p><h3>定位隐私</h3><p>位置权限仅用于前台获取地址。系统可能将坐标交给其地理编码服务；记录和完整备份可含定位坐标，Markdown 不含精确坐标，并可隐藏地点、行程与备注。</p><h3>电价资料</h3><p>省级政策时段是参考资料，不能直接当作所有公用充电站报价。服务费、计价类型、接电方式、供电区域、季节和政策更新都可能导致实际价格不同。查看资料来源并核对站点当日公示。</p><h3>界面版本</h3><p>v1.3.2 · 支持 Android 8.0 及以上。浏览器预览版仅保存在当前浏览器；不同设备的数据通过完整备份迁移。</p></div>`);}
document.addEventListener('click',e=>{
 const target=e.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,v=target.dataset.value,id=target.dataset.id;
 switch(a){case'navigate':screen=v;render();window.scrollTo(0,0);break;case'new':newRecord();break;case'close':closeRequested();break;case'keep-edit':document.getElementById('discard-notice')?.remove();discardPending=false;break;case'discard':closeSheet();break;case'detail':detail(id);break;case'edit':newRecord(id);break;case'delete':deleteRecord(id);break;case'category':category=v;recordLimit=80;render();break;case'more-records':recordLimit+=80;render();break;case'category-stats':category=v;screen='stats';render();window.scrollTo(0,0);break;case'grain':grain=v;render();break;case'prev-period':anchor=L.movePeriod(anchor,grain,-1);render();break;case'next-period':anchor=L.movePeriod(anchor,grain,1);render();break;case'current-period':anchor=L.todayTime().slice(0,10);render();break;case'reset-filter':listSearch='';listStart='';listEnd='';category='all';render();break;case'records':case'stats':screen=a;render();window.scrollTo(0,0);break;case'export':exportSheet();break;case'download-md':download(exportContent,'充电手账_'+L.todayTime().slice(0,10)+'.md','text/markdown');break;case'copy-md':copyMD();break;case'share-md':native.shareFile('充电手账_'+L.todayTime().slice(0,10)+'.md','text/markdown',exportContent);break;case'backup':backup();break;case'restore':chooseFile('restore');break;case'import':importSheet();break;case'choose-import':chooseFile('append');break;case'confirm-import':confirmImport();break;case'confirm-restore':if(pendingRestore&&persist(pendingRestore,true)){closeSheet();render();toast('备份已恢复');}break;case'settings':settings();break;case'about':about();break;case'recycle':recycle();break;case'recover':if(mutate(s=>{const i=s.trash.findIndex(r=>r.id===id);if(i>=0){const r=s.trash.splice(i,1)[0];delete r.deletedAt;s.records.push(r);}})){render();recycle();toast('记录已恢复');}break;case'locate':locate();break;
 }
});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='record-form')saveRecord();if(e.target.id==='settings-form'){try{const name=document.getElementById('f-vehicle').value.trim();if(!name||name.length>100)throw new Error('请输入100字以内的车辆名称');const budget=L.decimal(document.getElementById('f-budget').value,2,'预算');if(mutate(s=>{s.settings.vehicle=name;s.settings.budgetCents=budget;s.settings.autoLocate=document.getElementById('auto-locate').checked;s.settings.motion=document.getElementById('motion-mode').value;})){closeSheet();render();toast('设置已保存');}}catch(err){document.getElementById('settings-error').textContent=err.message;}}});
document.addEventListener('input',e=>{if(e.target.closest('#record-form'))formDirty=true;if(['f-amount','f-energy'].includes(e.target.id))updatePrice();if(e.target.id==='f-station'){const r=state.records.find(r=>r.station===e.target.value);if(r){document.getElementById('f-address').value=r.address||'';document.getElementById('f-operator').value=r.operator||'';formLocation=r.location||null;}}if(e.target.id==='record-search'){listSearch=e.target.value;recordLimit=80;clearTimeout(searchTimer);searchTimer=setTimeout(render,70);}});
document.addEventListener('change',e=>{const id=e.target.id;queueMicrotask(()=>{Interactions.updateControl(e.target);if(id==='f-precision')Interactions.updateControl(document.getElementById('f-time'));Interactions.enhance(document.getElementById('overlay-root'));});if(id==='f-precision'){const el=document.getElementById('f-time'),previous=el.value,kind=e.target.value;el.type={minute:'datetime-local',day:'date',month:'month'}[kind];el.value=kind==='month'?previous.slice(0,7):kind==='day'?(previous.length>=10?previous.slice(0,10):''):(previous.length>=16?previous:'');formDirty=true;}if(id==='f-kind'&&e.target.value==='trip_expense_summary'){document.querySelector('input[name="category"][value="business"]').checked=true;formDirty=true;}if(id==='list-start'||id==='list-end'){if(id==='list-start')listStart=e.target.value;else listEnd=e.target.value;if(listStart&&listEnd&&listStart>listEnd)toast('开始日期晚于结束日期，请调整筛选');render();}if(id==='tariff-province'){if(mutate(s=>s.settings.province=e.target.value)){tariffRegion=0;render();}}if(id==='tariff-month'){tariffMonth=Number(e.target.value);render();}if(id==='tariff-region'){tariffRegion=Number(e.target.value);render();}if(id.startsWith('export-'))updateExport();if(id==='backup-file'&&e.target.files[0]){e.target.files[0].text().then(receiveFile).catch(()=>toast('文件读取失败'));e.target.value='';}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)closeRequested();if(e.key==='Tab'&&modal){const sheet=document.querySelector('.sheet'),els=[...sheet.querySelectorAll('button,input,textarea,select,a[href],summary')].filter(el=>!el.disabled&&!el.classList.contains('native-control')&&el.getClientRects().length);if(els.length){const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===sheet)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
window.onNativeBack=()=>{if(Interactions.closePicker())return;if(modal){closeRequested();return;}if(screen!=='home'){screen='home';render();return;}if(native)native.finishApp();};
Interactions.configure({screen:()=>screen,page:pageDescriptor,reduced:reducedMotion,now:L.todayTime,onBackState:syncNativeBack,go:name=>{if(modal)return;screen=name;render();}});
render();

window.onNativeInsets=(top,right,bottom,left,gestureLeft=20,gestureRight=20)=>{const css=document.documentElement.style;for(const [key,value] of Object.entries({top,right,bottom,left}))css.setProperty('--safe-'+key,Math.max(0,value)+'px');window.__gestureInsets=[Math.max(20,gestureLeft),Math.max(20,gestureRight)];};
if(native&&typeof native.insets==='function'){try{window.__nativeInsets=JSON.parse(native.insets());}catch(_){}}
if(window.__nativeInsets?.length>=4)window.onNativeInsets(...window.__nativeInsets);
(async()=>{
 await Promise.race([document.fonts.ready,new Promise(resolve=>setTimeout(resolve,1200))]);
 await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
 Launch.prepare(reducedMotion(),native);
 const brand=document.querySelector('.brand-icon'),b=brand?.getBoundingClientRect();
 if(native&&typeof native.uiReady==='function')native.uiReady(b?.left||22,b?.top||22,b?.width||37,reducedMotion());

})();
